CountDownLatch latch = new CountDownLatch(3);
for (int i = 0; i < 3; i++) {
    executor.submit(() -> {
        try {
            loadPart();
        } finally {
            latch.countDown();
        }
    });
}
latch.await(); // 等三个任务全部完成

CyclicBarrier barrier = new CyclicBarrier(3, () -> mergeResult());
executor.submit(() -> {
    phaseOne();
    barrier.await();
    phaseTwo();
});

Semaphore pool = new Semaphore(10);
pool.acquire();
try {
    useLimitedResource();
} finally {
    pool.release();
}
